\label{ass:McDiarmid's}
There exists $p\in(1,2]$ such that
\begin{equation*}
V\coloneqq
\left\|
\sum_{k=1}^n
\|D_k(\bm{X})\|_{L_p}^{p}(\bm{X})
\right\|_{L_{\infty}(P_{\bm{X}})}
=
\left\|
\sum_{k=1}^n
\mathbb{E}^{(k)}\!\left[D_k(\bm{X})(\bm{X})^p\right]
\right\|_{L_{\infty}(P_{\bm{X}})}
<\infty.
\end{equation*}

\label{thm:heavy-tail}
Under \Cref{ass:McDiarmid's}, for every $t>0$,
\begin{equation}\label{eq:tail-p}
\mathbb P\!\left(f(\bm{X})-\mathbb{E}[f(\bm{X})]\ge t\right)
\le
\exp\!\left(
-\frac{p-1}{p}
\frac{t^{p/(p-1)}}{V^{1/(p-1)}}
\right).
\end{equation}
If $V=0$, then $f(\bm{X})$ is almost surely constant and the deviation probability is zero.

\noindent Equivalently, for every $\delta\in(0,1)$, with probability at least $1-\delta$,
\begin{equation}\label{eq:confidence-heavy-tail}
f(\bm{X})-\mathbb{E}[f(\bm{X})]
\le
V^{1/p}
\left(
\frac{p}{p-1}\ln\frac1\delta
\right)^{(p-1)/p}.
\end{equation}

For $u\ge0$ and $1<p\le2$,
\begin{equation}\label{eq:scalar}
  e^{-u}\le1-u+\frac{u^p}{p}
\end{equation}
as shown in \citet[Lemma B.8]{behnamnia2025logsumexponential}. Indeed, the two sides are equal at $u=0$ and 
\[
\frac{d}{du}\left(1-u+\frac{u^p}{p}-e^{-u}\right)=-1+u^{p-1}+e^{-u}\ge0.
\]
For $0\le u\le1$, we use $u^{p-1}\ge u$ and $e^{-u}\ge1-u$. For $u\ge1$, we use $u^{p-1}\ge1$. 

Fix $\beta>0$. Since $f(\bm{X})=\sup_kf(\bm{X})-D_k(\bm{X})(\bm{X})$ and $\sup_kf(\bm{X})$ does not depend on $X_k$,
\begin{align}
  \ln\mathbb E^{(k)}[e^{\beta f(\bm{X})}]
  -\beta\mathbb E^{(k)}[f(\bm{X})]
  &=
  \ln\mathbb E^{(k)}[e^{-\beta D_k(\bm{X})(\bm{X})}]
  +\beta\mathbb E^{(k)}[D_k(\bm{X})(\bm{X})]\notag\\
  &\le
  \frac{\beta^p}{p}
  \mathbb E^{(k)}[D_k(\bm{X})(\bm{X})^p]\text{ almost surely}.
  \label{eq:local-heavy-tail}
\end{align}
For the last inequality \eqref{eq:local-heavy-tail}, we apply \eqref{eq:scalar} with $u=\beta D_k(\bm{X})(\bm{X})\ge0$ a.s. and take expectations
\begin{equation*}
  \mathbb{E}^{(k)}\big[e^{-\beta D_k(\bm{X})(\bm{X})}\big]\le1-\beta\,\mathbb{E}^{(k)}[D_k(\bm{X})(\bm{X})]+\frac{\beta^p}{p}\,\mathbb{E}^{(k)}[D_k(\bm{X})(\bm{X})^p].
\end{equation*}
The left-hand side is positive, so the right-hand side is also positive. Since $\ln y\le y-1$ for $y>0$, 
\begin{align*}
    \ln\mathbb E^{(k)}[e^{-\beta D_k(\bm{X})(\bm{X})}]&\le\ln\left(1-\beta\,\mathbb{E}^{(k)}[D_k(\bm{X})(\bm{X})]+\frac{\beta^p}{p}\,\mathbb{E}^{(k)}[D_k(\bm{X})(\bm{X})^p]\right)\\
    &\le-\beta\,\mathbb{E}^{(k)}[D_k(\bm{X})(\bm{X})]+\frac{\beta^p}{p}\,\mathbb{E}^{(k)}[D_k(\bm{X})(\bm{X})^p].
\end{align*}
Adding $\beta\mathbb{E}^{(k)}[D_k(\bm{X})(\bm{X})]$ to both sides proves \eqref{eq:local-heavy-tail}. By \Cref{prop:bound}, there is a constant $b$ with $\beta (f-b)\le0$ a.s. Applying the reverse KL tensorization (\Cref{thm:reverse-kl}) to $h=\beta (f-b)$,
\begin{align*}
    \ln\mathbb E[e^{\beta(f(\bm{X})-\mathbb E[f(\bm{X})])}]&=
\ln\mathbb E[e^{\beta\left((f(\bm{X})-b)-\mathbb E[f(\bm{X})-b]\right)}]\\
  &\le\Big\|\sum_{k=1}^n\Big(\ln\mathbb{E}^{(k)}\big[e^{\beta f(\bm{X})}\big]-\beta\,\mathbb{E}^{(k)}[f(\bm{X})]\Big)\Big\|_{L_{\infty}(P_{\bm{X}})}\\
  &\le\frac{\beta^p}{p}\Big\|\sum_{k=1}^n\mathbb{E}^{(k)}\big[D_k(\bm{X})(\bm{X})^p\big]\Big\|_{L_{\infty}(P_{\bm{X}})}
  =\frac{V\beta^p}{p}.
\end{align*}
The last inequality is by \eqref{eq:local-heavy-tail}. Combined with Chernoff's inequality,
\begin{equation}\label{eq:reverse_chernoff}
  \mathbb P(f(\bm{X})-\mathbb E[f(\bm{X})]\ge t)
  \le
   \inf_{\beta>0}
  \exp\!\left(-\beta t+\ln\mathbb E[e^{\beta(f(\bm{X})-\mathbb E[f(\bm{X})])}]\right)
  \le
  \inf_{\beta>0}
  \exp\!\left(-\beta t+\frac{V\beta^p}{p}\right).
\end{equation}
If $V=0$, $f$ is almost surely constant, so the tail probability is zero. For $V>0$, taking $\beta=(t/V)^{1/(p-1)}$ proves \eqref{eq:tail-p}. The equivalent form \eqref{eq:confidence-heavy-tail} follows by solving for $t$.

\label{col:gen_empirical}
Assume $\overline M_n>0$. For every $t>0$, 

\begin{equation}\label{eq:mean-non-iid}
  \mathbb P\!\left(\overline X_n-\mathbb E[\overline X_n]\ge t\right)
  \le
  \exp\!\left(
    -\frac{p-1}{p}
    \frac{nt^{p/(p-1)}}{\overline M_n^{1/(p-1)}}
  \right).
\end{equation}

Equivalently, for every $\delta\in(0,1)$, with probability at least $1-\delta$,
\begin{equation}
\label{eq:non-iid-empirical-confidence}
  \overline X_n-\mathbb E[\overline X_n]
  \le \overline M_n^{1/p}
  \left(\frac{p}{p-1}\frac{\ln(1/\delta)}{n}\right)^{(p-1)/p}.
\end{equation}

\label{rmk:empirical_comparison} 
\citet[Theorem 2.6]{lei2026stability} followed by Markov's inequality, gives, for every $t>0$,

\begin{equation}\label{eq:polynomial-optimized}
\mathbb{P}(\overline X_n-\mathbb{E}\overline X_n\ge t) \le \min\bigg\{1,\; \min_{Q\ge1} \bigg[ 2(4Q)^p\frac{\overline M_n}{t^pn^{(p-1)}} + 2\left( 2e\,4^pQ^{p-1}\frac{\overline M_n}{t^pn^{(p-1)}} \right)^Q \bigg]\bigg\}.
\end{equation}

Each step of the derivation is sharp (see Appendix \ref{app:comparison}.) Nevertheless, for every $t>0$, the right-hand side of
\eqref{eq:polynomial-optimized} is strictly larger than that of the one-sided exponential bound \eqref{eq:mean-non-iid} in \Cref{col:gen_empirical}.

\label{prop:non-iid-direct-mom}
Assume 
\[V_{\mathrm{mom}}\coloneqq\sum_{j=1}^K\frac{1}{m_j^p}\sum_{i=1}^{m_j}M_{ji,p}>0.\]
For every $t>0$,
\begin{equation}
\label{eq:non-iid-direct-mom}
  \mathbb{P}(\widehat\mu_{\mathrm{MoM}}-\mathbb{E} \widehat\mu_{\mathrm{MoM}}\ge t)
  \le
  \exp\!\left(
    -\frac{p-1}{p}\,
    \frac{t^{p/(p-1)}}{V_{\mathrm{mom}}^{1/(p-1)}}
  \right).
\end{equation}

\label{rmk:mom_same_non_iid}
    Notice that if all the blocks have the same size $m_j=m$ in \Cref{prop:non-iid-direct-mom}, the deviation bound becomes
    \begin{equation}
\label{eq:equal-size-mom}
  \mathbb{P}(\widehat\mu_{\mathrm{MoM}}-\mathbb{E} \widehat\mu_{\mathrm{MoM}}\ge t)
  \le
  \exp\!\left(
    -\frac{p-1}{p}\,
    \frac{n}{\overline M_n^{1/(p-1)}}\left(\frac{t}{K}\right)^{p/(p-1)}
  \right),
\end{equation}
where $\overline M_n\coloneqq\frac 1n \sum_{j=1}^K\sum_{i=1}^mM_{ji,p}~(n=Km)$ is the averaged moment.

\label{col:mom_rate}
Let $X_1,\ldots,X_n$ be i.i.d.\ copies of $X$. For $t>\left(\frac{p}{p-1}\right)^{\frac{p-1}{p}} M_p^{1/p}\left(\frac{1}{m}\ln\frac{2K}{K+1}\right)^{\frac{p-1}{p}},$
\begin{equation*}
  \mathbb P\!\left(\widehat\mu_{\mathrm{MoM}}-\mu\ge t\right)
  \le
  \exp\!\left(-K d\left(\frac{K+1}{2K} \,\middle\Vert\, \overline q_t\right)\right),
\end{equation*}
where $d(\alpha\Vert \beta)\coloneqq \alpha\ln\frac{\alpha}{\beta}+(1-\alpha)\ln\frac{1-\alpha}{1-\beta}$ is the binary KL divergence, and $\overline q_t
  \coloneqq\exp\!\left(
    -\frac{p-1}{p}
    \frac{mt^{p/(p-1)}}{M_p^{1/(p-1)}}
  \right)$. If $K\ge\frac{\ln(1/\delta)}{\ln(2/\sqrt3)}$, with probability at least $1-\delta$,
\begin{equation}\label{eq:mom-confidence}
  \widehat\mu_{\mathrm{MoM}}-\mu
  \le
  M_p^{1/p}
  \left(
    \frac{p\ln4}{p-1}\frac{K}{n}
  \right)^{(p-1)/p}.
\end{equation}

\label{rmk:mom} Consider the same setting as \Cref{col:mom_rate}. For every $t>0$,
\begin{equation*}
\mathbb P(\widehat\mu_{\mathrm{MoM}}-\mu\ge t)
\le\binom{K}{(K+1)/2}\,\overline q_t^{\,\frac{K+1}{2}}=\binom{K}{(K+1)/2}\exp\left(-\frac{(p-1)(K+1)}{2pKM_p^{1/(p-1)}}nt^{p/(p-1)}\right).
\end{equation*}

\label{cor:empirical-processes}
Under the preceding assumptions, suppose that $\mathfrak{R}_n(\mathcal{L})<\infty$. For every $\delta\in(0,1)$, with probability at least $1-\delta$, for every $h\in\mathcal{H}$,

\begin{equation}\label{eq:ep-uniform-risk}
R(h)\le\widehat R_n(h)+2\mathfrak{R}_n(\mathcal{L})+M_p^{1/p}\left(\frac{p}{p-1}\frac{\ln(1/\delta)}{n}\right)^{(p-1)/p}.
\end{equation}

The tail bound \eqref{eq:non-iid-direct-mom} has the same form as \eqref{eq:tail-p} with $V$ replaced by $V_{\mathrm{mom}}$. The high-probability version follows by replacing $V$ by $V_{\mathrm{mom}}$ in \eqref{eq:confidence-heavy-tail}.

    Consider the same setting as \Cref{prop:non-iid-direct-mom}. For every $\delta\in(0,1)$, with probability at least
$1-\delta$,
\begin{equation*}
  \widehat\mu_{\mathrm{MoM}}-\mathbb{E} \widehat\mu_{\mathrm{MoM}}
  \le V_{\mathrm{mom}}^{1/p}
  \left(\frac{p}{p-1}\ln\frac{1}{\delta}\right)^{(p-1)/p}.
\end{equation*}

The proof of \Cref{col:mom_rate} relies on the next lemma.
\begin{lemma}\label{lem:mom}
Let $X_1,\ldots,X_n$ be i.i.d.\ copies of $X$. For $t>0$, define $\overline q_t\coloneqq\exp\!\left( -\frac{p-1}{p}\frac{mt^{p/(p-1)}}{M_p^{1/(p-1)}}\right).$\\
If $\overline q_t<\frac{K+1}{2K}$,
\begin{equation*}
  \mathbb P\!\left(\widehat\mu_{\mathrm{MoM}}-\mathbb{E}[X]\ge t\right)
  \le
  \exp\!\left(-K d((K+1)/2K \Vert\overline q_t)\right).
\end{equation*}
Also,
\begin{equation*}
  \mathbb P\!\left(
    \widehat\mu_{\mathrm{MoM}}-\mathbb{E}[X]
    \ge
    M_p^{1/p}
    \left(
      \frac{p\ln4}{p-1}\frac{K}{n}
    \right)^{(p-1)/p}
  \right)
  \le
  \left(\frac{\sqrt{3}}{2}\right)^K.
\end{equation*}
\end{lemma}
\begin{proofof}{\Cref{lem:mom}}
For $t>0$, define
\begin{align}
  \overline q_t
  &\coloneqq\exp\!\left(
    -\frac{p-1}{p}
    \frac{mt^{p/(p-1)}}{M_p^{1/(p-1)}}
  \right).
\end{align}
    Fix $j\in[K]$. Recall that $Y_j = \frac{1}{m} \sum_{i \in [m]} X_{ji}$. Since $X_{ji} \leq b$ a.s. for every $ji$, and the observations are independent, by \Cref{col:gen_empirical}, for every $t>0$ 
\begin{align*}
    \mathbb P(Y_j-\mu\ge t)
  &\le
    \exp
  \left(
    -\frac{p-1}{p}
    \frac{mt^{p/(p-1)}}{M_p^{1/(p-1)}}
  \right) = \overline q_t.
\end{align*}
Writing $k\coloneqq(K+1)/2$,
\begin{equation*}
\{\widehat\mu_{\mathrm{MoM}}-\mu\ge t\}
=\{\#\{j\in[K]: Y_j-\mu\ge t\}\ge k\}
=\bigcup_{\substack{S\subseteq[K]\\ |S|=k}}\bigcap_{j\in S}\{Y_j-\mu\ge t\}.
\end{equation*}
Hence, with Markov's inequality and by independence of the blocks,
\begin{equation}
    \mathbb P \left(\widehat\mu_{\mathrm{MoM}}-\mu \geq t\right) = \mathbb P \left(\sum_{j=1}^K\mathbf 1_{\{Y_j-\mu\ge t\}}\ge K \frac{K+1}{2K}\right)\le \inf_{\lambda>0}\exp
  \left(
    -\lambda K\frac{K+1}{2K}
  \right)\prod_{j=1}^K
  \mathbb E
  \left[
    e^{\lambda\mathbf 1_{\{Y_j-\mu\ge t\}}}
  \right].
\end{equation}
For every $j$,
\begin{align*}
  \mathbb E
  \left[
    e^{\lambda\mathbf 1_{\{Y_j-\mu\ge t\}}}
  \right]
  =
  1+
  (e^\lambda-1)
  \mathbb P(Y_j-\mu\ge t)
  \le
  1-\overline q_t+\overline q_te^\lambda.
\end{align*}
It follows that
\begin{align}
  \mathbb P
  \left(
    \widehat\mu_{\mathrm{MoM}}-\mu\ge t
  \right)
  \le
  \inf_{\lambda>0}
  \exp
  \left[
    K
    \left(
      -\lambda \frac{K+1}{2K}
      +
      \ln
      \left(
        1-\overline q_t+\overline q_te^\lambda
      \right)
    \right)
  \right].
  \label{eq:mom-chernoff}
\end{align}
Since $\overline q_t<\frac{K+1}{2K}$, the number
\[
  \lambda
  =
  \ln
  \left(
    \frac{\frac{K+1}{2K}(1-\overline q_t)}
         {\overline q_t(1-\frac{K+1}{2K})}
  \right)
\]
is positive. For this choice,
\begin{align*}
  1-\overline q_t+\overline q_te^\lambda
  =
  1-\overline q_t
  +
  \overline q_t
  \frac{\frac{K+1}{2K}(1-\overline q_t)}
       {\overline q_t(1-\frac{K+1}{2K})}
  =
  (1-\overline q_t)
  \left(
    1+\frac{\frac{K+1}{2K}}{1-\frac{K+1}{2K}}
  \right)
  =
  \frac{1-\overline q_t}{1-\frac{K+1}{2K}}.
\end{align*}
Substituting this value of $\lambda$ into the exponent in
\eqref{eq:mom-chernoff} gives
$-\lambda \frac{K+1}{2K}
  +
  \ln
  \left(
    1-\overline q_t+\overline q_te^\lambda
  \right)=
  -d(\frac{K+1}{2K}\Vert\overline q_t).
$
Therefore,
\[
  \mathbb P
  \left(
    \widehat\mu_{\mathrm{MoM}}-\mu\ge t
  \right)
  \le
  \exp
  \left(
    -K d((K+1)/2K \Vert\overline q_t)
  \right).
\]

    For the second part, fix some $\rho$ such that  $0<\rho<\frac{K+1}{2K}$.
    \begin{equation*}
        \exp\!\left(
    -\frac{p-1}{p}
    \frac{mt^{p/(p-1)}}{M_p^{1/(p-1)}}
  \right)=\rho
  \Leftrightarrow t=M_p^{1/p}
    \left(
      \frac{p\ln(1/\rho)}{p-1}\frac{K}{n}
    \right)^{(p-1)/p}
    \end{equation*}
    For $t^*=M_p^{1/p}
    \left(
      \frac{p\ln(1/\rho)}{p-1}\frac{K}{n}
    \right)^{(p-1)/p}$, $\overline q_{t^*}=\rho<\frac{K+1}{2K}$. Using the first part, 
    \begin{equation*}
  \mathbb P\!\left(\widehat\mu_{\mathrm{MoM}}-\mu\ge M_p^{1/p}
    \left(
      \frac{p\ln(1/\rho)}{p-1}\frac{K}{n}
    \right)^{(p-1)/p}\right)
  \le
  \exp\!\left(-K d((K+1)/2K \Vert\rho )\right).
\end{equation*}
The claim follows by taking $\rho=\frac{1}{4}$ and $d\left((K+1)/2K\Vert1/4\right)\ge d(1/2\Vert1/4)=\ln (2/\sqrt{3}).$
\end{proofof}
Using the first part of \Cref{lem:mom} and the equivalence 
\[\overline q_t<\frac{K+1}{2K} \Leftrightarrow t>\left(\frac{p}{p-1}\right)^{\frac{p-1}{p}} M_p^{1/p}\left(\frac{1}{m}\ln\frac{2K}{K+1}\right)^{\frac{p-1}{p}}\]
proves the first part of the claim in \Cref{col:mom_rate}. 
Using the second part of \Cref{lem:mom} and the equivalence of $(\sqrt{3}/2)^K\le\delta \Leftrightarrow K\ge\frac{\ln(1/\delta)}{\ln(2/\sqrt3)}$ proves the second part of the claim in \Cref{col:mom_rate}.

